import{_ as i,l as n,o as a,c as s,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"写合并缓冲","description":"","frontmatter":{"title":"写合并缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-combining.md","filePath":"cs/write-combining.md","lastUpdated":1789023840000}'),h={name:"cs/write-combining.md"};function C(E,e,m,f,_,B){const o=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="写合并缓冲" tabindex="-1">写合并缓冲 <a class="header-anchor" href="#写合并缓冲" aria-label="Permalink to &quot;写合并缓冲&quot;">​</a></h1><div class="epigraph"><p>连续的窄 store 不必每次占一条总线事务；在缓冲里把同一行的字节拼齐，再按整行或扇区写出去。</p><footer>—— 据 Intel 软件开发者手册对 write-combining 的描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/line-size-sector">上一课</a> 允许按扇区传输。store 路径上还有更细的东西：图形、DMA、非缓存映射的帧缓冲常常是一串 4–8B 写。若每条都按 <a href="/cs/mesi-protocol">MESI</a> 升级整行，带宽与作废都浪费。本课不重选行大小。缺口是<strong>写合并缓冲（WCB / WC）：在离开核之前把同行字节合并。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UC 或 WC 内存类型上，store 不进 L1 常规写分配，否则会污染 cache。<a href="/cs/retire-precise-exception">退休</a> 后 store 仍要变成对设备或 DRAM 可见。逐条发 8B 事务，互联效率极差。缺口不是压缩，而是<strong>按物理行地址聚合未完成的 store，掩码记录哪些字节有效，满了或 fence 时一齐发出。</strong></p><p><span class="marginnote">x86 的 WC 内存类型允许写合并与弱序；fence / 串行化指令会冲刷合并缓冲。这是微结构缓冲，也是内存模型可见的宽松点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若干项，每项：行地址、字节掩码、数据。退休 store 若地址匹配则并入；否则分配新项或逐出最旧项。逐出：按掩码发写组合事务（或先读-改-写若协议要求）。fence、I/O、过深依赖则 drain。</p>',8)),(a(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E9%80%80%E4%BC%91%E7%9A%84%E7%AA%84%20store%22%5D%20--%3E%20WCB%5B%22%E6%8C%89%E8%A1%8C%E5%90%88%E5%B9%B6%22%5D%0A%20%20WCB%20--%3E%7C%22%E5%90%8C%E8%A1%8C%22%7C%20MERGE%5B%22%E6%9B%B4%E6%96%B0%E6%8E%A9%E7%A0%81%E4%B8%8E%E5%AD%97%E8%8A%82%22%5D%0A%20%20WCB%20--%3E%7C%22%E6%BB%A1%E6%88%96%20fence%22%7C%20OUT%5B%22%E5%8F%91%E5%87%BA%E7%BB%84%E5%90%88%E5%86%99%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对 cacheable 写回内存，常规 SQ + 写分配已经在行内合并；WCB 的主战场是 WC/UC 与某些 streaming store。与 <a href="/cs/lsq-disambiguation">LSQ</a>：转发规则在 WC 区域更弱，程序员不能假设马上被后续 load 看见——这是模型课与 fence 课的接口，本课只要求缓冲在 drain 前可以乱序发出不同行。</p><p>GPU 的 store buffer / 合并单元更激进，后课合并访存会再遇到「按行拼事务」，先在 CPU 侧把 WCB 钉住。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DMA 描述符环的驱动写法展开。也不把事务内存的写集合当成 WCB。fence 的代价下一单元末才专讲；这里只承认 drain 是正确性点。TLB 多级是下一课：合并用的是物理行地址，必须已经翻译完。</p><p>后课默认：窄 store 可以在核边合成较宽的写。翻译本身有层次，下一课 TLB 与 PWC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写合并把同行窄 store 合成一次事务，主要用于 WC/UC 与流式写。</li><li>fence 与缓冲满会强制 drain。</li><li>多级 TLB 与页表缓存是下一课翻译层次。</li><li>出处：Intel SDM（WC）；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const b=i(h,[["render",C]]);export{u as __pageData,b as default};
